sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

       var ga = new GlideAjax('x_1523510_alloca_0.AllocateNowUtils');
    ga.addParam('sysparm_name', 'isDuplicateBase');
    ga.addParam('sysparm_field_name', 'name');
    ga.addParam('sysparm_field_value', newValue);
    ga.addParam('sysparm_current_base', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.clearValue('name');
			g_form.addErrorMessage(
                'A base with this name already exists.'
            );
        }
    });

}
